import csv
from collections import defaultdict
manager_values = defaultdict(float)
with open('/root/2025-q3/INFOTABLE.tsv', 'r') as f:
    reader = csv.DictReader(f, delimiter='\t')
    for row in reader:
        if '69608A108' in row['CUSIP']:
            manager_values[row['ACCESSION_NUMBER']] += float(row['VALUE'])
manager_names = {}
with open('/root/2025-q3/COVERPAGE.tsv', 'r') as f:
    reader = csv.DictReader(f, delimiter='\t')
    for row in reader:
        acc = row['ACCESSION_NUMBER']
        if acc in manager_values:
            manager_names[acc] = row['FILINGMANAGER_NAME']
for acc, val in manager_values.items():
    name = manager_names.get(acc, acc)
    if 'BlackRock' in name:
        print(f'{name}: {val}')
